// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProviderModelCatalog) predicate.ProviderModelCatalog {
	return predicate.ProviderModelCatalog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProviderModelCatalog) predicate.ProviderModelCatalog {
	return predicate.ProviderModelCatalog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProviderModelCatalog) predicate.ProviderModelCatalog {
	return predicate.ProviderModelCatalog(sql.NotPredicates(p))
}
